<?php
declare(strict_types=1);

final class SupplyLots
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private static function fail(string $message='Dữ liệu nguồn cung không hợp lệ.'):never{throw new HttpError(400,$message);}
    private static function uuid(mixed $id):bool{return is_string($id)&&(bool)preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$id);}
    private static function integer(mixed $v,int $min,int $max):int{if(!is_int($v)||$v<$min||$v>$max)self::fail();return $v;}
    private static function text(mixed $v,int $max):string{if(!is_string($v))self::fail();$v=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$v);if($v===null||strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2>$max)self::fail();return $v;}
    private static function date(mixed $v):string{if(!is_string($v))self::fail();Pricing::validateDate($v);return $v;}
    private static function fingerprint(array $input):string{return hash('sha256',json_encode($input,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_LINE_TERMINATORS|JSON_THROW_ON_ERROR));}
    private function lock():void{if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');}
    private function audit(string $actor,string $action,string $id):void{$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,$action,$id]);}
    private static function validate(array $raw):array
    {
        if(array_diff(array_keys($raw),['unlimited','id','supplierId','productId','variantId','customerType','unitCost','quantity','validFrom','validTo','priority','note']))self::fail();$unlimited=$raw['unlimited'] ?? false;if(!is_bool($unlimited)||!self::uuid($raw['id'] ?? null)||!self::uuid($raw['supplierId'] ?? null))self::fail();foreach(['productId','variantId'] as $key)if(!is_string($raw[$key] ?? null)||!preg_match('/^[a-zA-Z0-9_-]{1,80}$/D',$raw[$key]))self::fail();if(!in_array($raw['customerType'] ?? null,Pricing::GROUPS,true))self::fail();
        // Order matches the source Zod object so original request hashes remain useful.
        $out=['unlimited'=>$unlimited,'id'=>$raw['id'],'supplierId'=>$raw['supplierId'],'productId'=>$raw['productId'],'variantId'=>$raw['variantId'],'customerType'=>$raw['customerType'],'unitCost'=>self::integer($raw['unitCost'] ?? null,0,100000000)];if($unlimited&&array_key_exists('quantity',$raw)||!$unlimited&&!array_key_exists('quantity',$raw))self::fail('Nguồn theo đơn không nhập số lượng; lô nhập sẵn cần số lượng.');if(!$unlimited)$out['quantity']=self::integer($raw['quantity'],1,1000000);$out['validFrom']=self::date($raw['validFrom'] ?? null);$out['validTo']=self::date($raw['validTo'] ?? null);$out['priority']=self::integer($raw['priority'] ?? 100,0,10000);$out['note']=self::text($raw['note'] ?? '',1000);if($out['validFrom']>$out['validTo']||!$unlimited&&$out['unitCost']*$out['quantity']>15000000000)self::fail('Khoảng ngày hoặc giá trị lô vượt giới hạn 15 tỷ VND.');return $out;
    }
    public function list():array
    {
        $rows=$this->query('SELECT l.*,COALESCE(a.used,0) AS used,COALESCE(p.purchased,0) AS purchased_quantity FROM jingo_supply_lots l LEFT JOIN (SELECT lot_id,SUM(quantity) AS used FROM jingo_supply_allocations WHERE released=0 GROUP BY lot_id) a ON a.lot_id=l.id LEFT JOIN (SELECT lot_id,SUM(quantity) AS purchased FROM jingo_supply_purchases GROUP BY lot_id) p ON p.lot_id=l.id ORDER BY l.created_at DESC,l.id')->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$row){unset($row['request_hash']);foreach(['unit_cost','version','priority','used','purchased_quantity'] as $key)$row[$key]=(int)$row[$key];foreach(['enabled','archived','unlimited'] as $key)$row[$key]=(bool)$row[$key];$row['total_quantity']=$row['unlimited']?null:(int)$row['total_quantity'];$row['remaining']=$row['unlimited']?null:$row['total_quantity']-$row['used'];$row['data']=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);}unset($row);return $rows;
    }
    public function receive(array $raw,string $actor,bool $batch=false):array
    {
        if($batch){if(array_keys($raw)!==['lots']||!is_array($raw['lots'])||!array_is_list($raw['lots'])||count($raw['lots'])<1||count($raw['lots'])>6)self::fail();$inputs=$raw['lots'];}else $inputs=[$raw];$inputs=array_map(function($v){if(!is_array($v))self::fail();return self::validate($v);},$inputs);if(count(array_unique(array_column($inputs,'id')))!==count($inputs)||count(array_unique(array_column($inputs,'customerType')))!==count($inputs))self::fail('Mỗi nhóm khách một dòng, không lặp mã lô.');foreach(['supplierId','productId','variantId'] as $key)if(count(array_unique(array_column($inputs,$key)))!==1)self::fail('Các dòng cần cùng nhà cung cấp, sản phẩm và gói.');
        $this->db->beginTransaction();try{$this->lock();foreach($inputs as $input){$hashInput=$input;if(!$input['unlimited'])unset($hashInput['unlimited']);$hash=self::fingerprint($hashInput);$prior=$this->query('SELECT request_hash FROM jingo_supply_lots WHERE id=? FOR UPDATE',[$input['id']])->fetchColumn();if($prior!==false){if(!hash_equals($prior,$hash))throw new HttpError(409,'Mã lô đã dùng với dữ liệu khác.');continue;}$product=$this->query('SELECT data FROM jingo_products WHERE id=?',[$input['productId']])->fetchColumn();$supplier=$this->query('SELECT data FROM jingo_suppliers WHERE id=?',[$input['supplierId']])->fetchColumn();$p=$product===false?null:json_decode($product,true,512,JSON_THROW_ON_ERROR);$s=$supplier===false?null:json_decode($supplier,true,512,JSON_THROW_ON_ERROR);if(!$p||!$s||$s['status']!=='ACTIVE')self::fail('Chọn sản phẩm và nhà cung cấp đang hoạt động.');$variant=null;foreach($p['variants'] as $v)if($v['id']===$input['variantId'])$variant=$v;if(!$variant||!array_key_exists($input['customerType'],$variant['prices']))self::fail('Gói hoặc nhóm khách không hợp lệ.');$data=['supplierName'=>$s['name'],'productName'=>$p['name'],'variantName'=>$variant['name'],'note'=>$input['note']];$this->query('INSERT INTO jingo_supply_lots(id,request_hash,supplier_id,product_id,variant_id,customer_type,unit_cost,total_quantity,valid_from,valid_to,priority,data,unlimited) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',[$input['id'],$hash,$input['supplierId'],$input['productId'],$input['variantId'],$input['customerType'],$input['unitCost'],$input['quantity'] ?? 0,$input['validFrom'],$input['validTo'],$input['priority'],json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),(int)$input['unlimited']]);$this->audit($actor,'supply.receive',$input['id']);}$this->db->commit();return ['ok'=>true];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();if($e instanceof PDOException&&($e->errorInfo[1] ?? null)===1062)throw new HttpError(409,'Mã lô đã được dùng.');throw $e;}
    }
    public function manage(string $id,array $input,string $actor,bool $config=false):array
    {
        if(!self::uuid($id))throw new HttpError(404,'Không tìm thấy nguồn.');$keys=$config?['version','enabled','priority']:['version','action','unitCost','validFrom','validTo','priority','note'];if(array_diff(array_keys($input),$keys))self::fail();$version=self::integer($input['version'] ?? null,1,2147483646);if($config){if(!is_bool($input['enabled'] ?? null))self::fail();self::integer($input['priority'] ?? null,0,10000);}else{if(!in_array($input['action'] ?? null,['EDIT','DELETE','RESTORE'],true))self::fail();foreach(['unitCost'=>100000000,'priority'=>10000] as $key=>$max)if(array_key_exists($key,$input))self::integer($input[$key],0,$max);foreach(['validFrom','validTo'] as $key)if(array_key_exists($key,$input))self::date($input[$key]);if(array_key_exists('note',$input))$input['note']=self::text($input['note'],1000);}
        $this->db->beginTransaction();try{$this->lock();$lot=$this->query('SELECT * FROM jingo_supply_lots WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$lot)throw new HttpError(404,'Không tìm thấy nguồn.');if((int)$lot['version']!==$version)throw new HttpError(409,'Nguồn đã thay đổi. Tải lại trước khi lưu.');$resultId=$id;
            if($config){if($lot['archived'])self::fail('Khôi phục nguồn trước khi bật.');if($input['enabled']){$supplier=json_decode($this->query('SELECT data FROM jingo_suppliers WHERE id=?',[$lot['supplier_id']])->fetchColumn(),true,512,JSON_THROW_ON_ERROR);if($supplier['status']!=='ACTIVE')self::fail('Nhà cung cấp đã lưu trữ.');}$this->query('UPDATE jingo_supply_lots SET enabled=?,priority=?,version=version+1 WHERE id=?',[(int)$input['enabled'],$input['priority'],$id]);}
            elseif($input['action']==='EDIT'){
                if($lot['archived'])self::fail('Khôi phục nguồn trước khi sửa.');$cost=$input['unitCost'] ?? (int)$lot['unit_cost'];$from=$input['validFrom'] ?? $lot['valid_from'];$to=$input['validTo'] ?? $lot['valid_to'];$priority=$input['priority'] ?? (int)$lot['priority'];$data=json_decode($lot['data'],true,512,JSON_THROW_ON_ERROR);$data['note']=$input['note'] ?? $data['note'] ?? '';if($from>$to)self::fail('Kiểm tra khoảng ngày.');if(!$lot['unlimited']&&$cost!==(int)$lot['unit_cost'])self::fail('Lô nhập sẵn giữ nguyên giá mua đã ghi nhận.');$used=$this->query('SELECT order_id FROM jingo_supply_allocations WHERE lot_id=? LIMIT 1',[$id])->fetchColumn();
                if($cost!==(int)$lot['unit_cost']&&$used){$supplier=json_decode($this->query('SELECT data FROM jingo_suppliers WHERE id=?',[$lot['supplier_id']])->fetchColumn(),true,512,JSON_THROW_ON_ERROR);if($supplier['status']!=='ACTIVE')self::fail('Nhà cung cấp đã lưu trữ.');$h=bin2hex(random_bytes(16));$resultId=substr($h,0,8).'-'.substr($h,8,4).'-4'.substr($h,13,3).'-8'.substr($h,17,3).'-'.substr($h,20,12);$this->query('INSERT INTO jingo_supply_lots(id,request_hash,supplier_id,product_id,variant_id,customer_type,unit_cost,total_quantity,valid_from,valid_to,priority,data,unlimited,enabled) VALUES (?,?,?,?,?,?,?,0,?,?,?,?,1,?)',[$resultId,self::fingerprint(['lotId'=>$id,'input'=>$input,'resultId'=>$resultId]),$lot['supplier_id'],$lot['product_id'],$lot['variant_id'],$lot['customer_type'],$cost,$from,$to,$priority,json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),(int)$lot['enabled']]);$this->query('UPDATE jingo_supply_lots SET archived=1,enabled=0,version=version+1 WHERE id=?',[$id]);}
                else $this->query('UPDATE jingo_supply_lots SET unit_cost=?,valid_from=?,valid_to=?,priority=?,data=?,version=version+1 WHERE id=?',[$cost,$from,$to,$priority,json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$id]);
            }else{if(($input['action']==='DELETE')===(bool)$lot['archived'])throw new HttpError(409,'Trạng thái nguồn đã thay đổi.');$this->query('UPDATE jingo_supply_lots SET archived=?,enabled=0,version=version+1 WHERE id=?',[(int)($input['action']==='DELETE'),$id]);}
            $this->audit($actor,$config?'supply.configure':'supply.'.strtolower($input['action']),$id);$this->db->commit();return ['ok'=>true,'id'=>$resultId,'replaced'=>$resultId!==$id];
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
}
